body.script:
(function(){
  const W = 714;
  const rect = document.getElementById('revealRect');
  const cursor = document.getElementById('cursorLine');
  const DURATION = 2800; // ms - tune for typing speed

  // small step function gives a "typed in chunks" feel instead of a smooth linear wipe
  const STEPS = 60;

  function run(){
    const start = performance.now();
    rect.setAttribute('width', 0);
    cursor.setAttribute('x', 0);
    cursor.setAttribute('opacity', 0.85);

    function frame(now){
      const t = Math.min(1, (now - start) / DURATION);
      // quantize progress into STEPS chunks so it reads like typing, not a smooth slide
      const stepped = Math.floor(t * STEPS) / STEPS;
      const w = stepped * W;
      rect.setAttribute('width', w.toFixed(2));
      cursor.setAttribute('x', Math.max(0, w - 5).toFixed(2));
      if (t >= 1) {
        rect.setAttribute('width', W);
        cursor.setAttribute('opacity', 0);
      }
      if (t < 1) requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);
  }
  run();
  window.replayReveal = run;
})();
